// Per-sponsor rollup from bdctransparency.io's company-sponsor mapping
// intersected with our parsed SOI position data across all 14 covered BDCs.
//
// Credit-lens fields are POSITION-COUNT WEIGHTED across each BDC's latest
// quarter (positions it no longer holds are not counted). Funded debt
// positions only (scripts/marks.py instrument rule) — equity / preferred /
// warrants / units / LP interests / unfunded commitments are excluded so the
// mark-below-par and PIK signals reflect credit quality, not capital-structure
// composition.
//
// pct_below_95 / pct_below_90: % of positions with a price mark (fair value ÷
//   par, the same mark as the credit heatmaps) marked below 95c / 90c of par;
//   n_positions_marked is the denominator; null when none has a mark.
//
// pct_non_accrual: denominator counts only positions whose non-accrual status
//   is decoded for that quarter (unknown status is left out, never zero).
// pct_modified: denominator counts only positions with parseable PIK info
//   (so a loan-life cash-to-PIK flip can be detected).
// pct_pik_now: backwards-compatible known-positive lower bound over the
//   source-aware applicable denominator (observed + unknown). Unknown positions
//   are included in pct_pik_now_upper. Rows classified not_applicable remain in
//   sponsor exposure metrics but are excluded from both PIK bounds.

export interface SponsorIndex {
  sponsor_slug: string;
  sponsor: string;
  n_companies: number;        // distinct borrowers in our index attributed to sponsor
  n_positions: number;        // total debt positions across all BDCs
  avg_holders: number;        // mean # of BDC holders per attributed company
  total_fv: number;           // sum of latest-quarter FV across those positions, USD

  // Credit lens — position-count weighted percentages (0-100)
  pct_below_95: number | null; // % of marked positions below 95¢ of par
  pct_below_90: number | null; // % of marked positions below 90¢ of par
  n_positions_marked: number;  // positions with a price mark (the below-X denominator)
  pct_non_accrual: number;    // % positions tagged non-accrual (NA-coverage subset)
  n_positions_na: number;     // denominator for pct_non_accrual
  pct_pik_now: number;        // known-positive lower bound, % of applicable positions
  pct_pik_now_upper: number;  // lower bound + unknown applicable positions
  n_positions_pik_applicable: number; // denominator for both PIK bounds
  n_positions_pik_observed: number;
  n_positions_pik_unknown: number;
  pik_observation_coverage_pct: number | null; // observed / (observed + unknown)
  pik_publication_status: "unavailable" | "fully_observed" | "bounded";
  pik_publication_reason: string;
  pik_metric_version: "sponsor_pik_position_bounds_v1";
  pct_modified: number;       // % positions where loan flipped cash→PIK in window
  n_positions_mod: number;    // denominator for pct_modified

  // Lifetime distress lens (league table) — completed exits across our panel
  n_exits: number;            // completed exits attributed to the sponsor
  n_distress: number;         // of those, exits that ended in distress
  pct_exits_distress: number; // % of exits that ended in distress (NA / <85¢ / write-off pattern)
  realized_loss_usd: number;  // realized-loss proxy summed over distress exits, USD
}

